import numpy as np
def f(inp):
    g=np.array(inp); n=g.shape[0]; s=int(g[0].argmax())
    out=[[0]*n for _ in range(n)]
    M=n-1-s; cl=(n-1-3*s)%4
    for r in range(n):
        for c in range(n):
            v=r+c; u=r-c
            arm = (v==s and 0<=r<=s) or (u==-s and 0<=r<=M)
            if arm: out[r][c]=2; continue
            if v>=s and u>-M and (u-cl)%4==0 and (v-s)%2==0:
                out[r][c]=1
    return out

