import numpy as np
def solve(gi):
    g=np.array(gi); n=g.shape[0]; s=int(np.argmax(g[0]))
    D=[-s+4*k for k in range(1,n)]   # diffs
    V=[s+2*m for m in range(1,n)]   # anti-diag sums
    pred=[[0]*n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            u,vv=r-c,r+c
            if vv==s and 0<=r<=s: continue          # left arm
            if u==-s and 0<=c<=s: continue          # right arm
            if u in D and vv in V:
                pred[r][c]=1
    return pred
